describe('ToolRegistry input validation', () => {
  it('rejects an enum-violating input without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'set_unit',
        description: 'Set the display unit',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('set_unit', {unit: 'kelvin'});

    expect({executorCalls, rejected: response.result.includes('unit')}).toEqual({
      executorCalls: 0,
      rejected: true,
    });
  });
});

